#include <stdio.h>
#include <string.h>

#define MAX_EQ 200
#define MAX_VAR 676

static int coef[MAX_EQ][MAX_VAR];
static int unknown_count[MAX_EQ];
static __int128 remaining[MAX_EQ];
static int solved[MAX_VAR];
static __int128 value[MAX_VAR];
static int present[MAX_VAR];

static void print_int128(__int128 x) {
    char buf[64];
    int n = 0;
    unsigned __int128 magnitude;

    if (x < 0) {
        putchar('-');
        magnitude = (unsigned __int128)(-(x + 1)) + 1;
    } else {
        magnitude = (unsigned __int128)x;
    }

    do {
        buf[n++] = (char)('0' + magnitude % 10);
        magnitude /= 10;
    } while (magnitude > 0);

    while (n > 0)
        putchar(buf[--n]);
}

int main(void) {
    int L, C;
    if (scanf("%d %d", &L, &C) != 2)
        return 0;

    int equations = L + C;

    for (int r = 0; r < L; r++) {
        for (int c = 0; c < C; c++) {
            char name[3];
            scanf("%2s", name);
            int v = (name[0] - 'a') * 26 + (name[1] - 'a');
            present[v] = 1;

            if (coef[r][v]++ == 0)
                unknown_count[r]++;
            if (coef[L + c][v]++ == 0)
                unknown_count[L + c]++;
        }
        long long sum;
        scanf("%lld", &sum);
        remaining[r] = sum;
    }

    for (int c = 0; c < C; c++) {
        long long sum;
        scanf("%lld", &sum);
        remaining[L + c] = sum;
    }

    int total_vars = 0;
    for (int v = 0; v < MAX_VAR; v++)
        total_vars += present[v];

    int solved_vars = 0;
    while (solved_vars < total_vars) {
        int equation = -1;
        int variable = -1;

        for (int e = 0; e < equations && equation == -1; e++) {
            if (unknown_count[e] != 1)
                continue;

            for (int v = 0; v < MAX_VAR; v++) {
                if (coef[e][v] > 0 && !solved[v]) {
                    equation = e;
                    variable = v;
                    break;
                }
            }
        }

        if (equation == -1)
            return 0;

        value[variable] = remaining[equation] / coef[equation][variable];
        solved[variable] = 1;
        solved_vars++;

        for (int e = 0; e < equations; e++) {
            if (coef[e][variable] > 0) {
                remaining[e] -= (__int128)coef[e][variable] * value[variable];
                unknown_count[e]--;
            }
        }
    }

    for (int v = 0; v < MAX_VAR; v++) {
        if (present[v]) {
            putchar('a' + v / 26);
            putchar('a' + v % 26);
            putchar(' ');
            print_int128(value[v]);
            putchar('\n');
        }
    }

    return 0;
}
