            int v = (name[0] - 'a') * 26 + (name[1] - 'a');
            coef[i][v]++;
            coef[L + j][v]++;
            present[v] = 1;
        }
        scanf("%lld", &residual[i]);
    }

    for (int j = 0; j < C; j++) {
        scanf("%lld", &residual[L + j]);
    }

    int queue[MAX_EQS];
    int head = 0, tail = 0;

    for (int e = 0; e < equations; e++) {
        for (int v = 0; v < MAX_VARS; v++) {
            if (coef[e][v] > 0) unknown_count[e]++;
        }
        if (unknown_count[e] == 1) queue[tail++] = e;
    }

    while (head < tail) {
        int e = queue[head++];
        if (unknown_count[e] != 1) continue;

        int v = -1;
        for (int k = 0; k < MAX_VARS; k++) {
            if (coef[e][k] > 0 && !solved[k]) {
                v = k;
                break;
            }
        }
        if (v == -1) continue;

        value[v] = residual[e] / coef[e][v];
        solved[v] = 1;

        for (int q = 0; q < equations; q++) {
            if (coef[q][v] > 0) {
                residual[q] -= (long long)coef[q][v] * value[v];
                unknown_count[q]--;
                if (unknown_count[q] == 1) queue[tail++] = q;
            }
        }
    }

    for (int v = 0; v < MAX_VARS; v++) {
        if (present[v]) {
            printf("%c%c %lld\n", 'a' + v / 26, 'a' + v % 26, value[v]);
        }
    }

    return 0;
}
